#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    getline(cin, s);
    int x = 0, y = 0;
    stringstream ss(s);
    string cmd;
    while (getline(ss, cmd, ';')) {
        if (cmd.size() < 2) continue;
        int step = stoi(cmd.substr(1));
        if (cmd[0] == 'A') x -= step;
        else if (cmd[0] == 'D') x += step;
        else if (cmd[0] == 'W') y += step;
        else if (cmd[0] == 'S') y -= step;
    }
    cout << x << "," << y << endl;
    return 0;
}

substr(pos, len)：第一个参数是起点，第二个是长度，不是终点。多组输入、每组一行，用 while (getline(cin, s)) 最保险。
